const updateAutomation = `-- name: UpdateAutomation :one
UPDATE automations SET
    name = coalesce($1, name),
    description = coalesce($2, description),
    active = coalesce($3, active),
    trigger_type = coalesce($4, trigger_type),
    trigger = coalesce($5, trigger),
    steps = coalesce($6, steps),
    program = coalesce($7, program),
    -- Moving nodes on the canvas is not a new version: runs continue.
    layout = coalesce($8, layout),
    setup = coalesce($9, setup),
    version = CASE WHEN $7::jsonb IS NOT NULL OR $5::jsonb IS NOT NULL THEN version + 1 ELSE version END,
    updated_at = now()
WHERE id = $10
RETURNING id, name, description, active, trigger_type, trigger, steps, program, version, created_by, created_at, updated_at, layout, setup, preset_key, preset_version, tenant_id
`

type UpdateAutomationParams struct {
	Name        *string
	Description *string
	Active      *bool
	TriggerType *string
	Trigger     []byte
	Steps       []byte
	Program     []byte
	Layout      []byte
	Setup       []byte
	ID          uuid.UUID
}

func (q *Queries) UpdateAutomation(ctx context.Context, arg UpdateAutomationParams) (Automation, error) {
	row := q.db.QueryRow(ctx, updateAutomation,
		arg.Name,
		arg.Description,
		arg.Active,
		arg.TriggerType,
		arg.Trigger,
		arg.Steps,
		arg.Program,
		arg.Layout,
		arg.Setup,
		arg.ID,
	)
	var i Automation
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Description,
		&i.Active,
		&i.TriggerType,
		&i.Trigger,
		&i.Steps,
		&i.Program,
		&i.Version,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Layout,
		&i.Setup,
		&i.PresetKey,
		&i.PresetVersion,
		&i.TenantID,
	)
	return i, err
}

